metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform." {
    model {
        customer = person "Customer" "A person who uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up the status of their shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Server-side service"
            database = container "Database" "Stores shipment and dispatch records." "Relational database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization, used to send customer notification emails." "External"

        customer -> webPortal "looks up the status of their parcels" "Web browser"
        webPortal -> database "reads shipment records from" "SQL"
        dispatchService -> database "writes dispatch records to" "SQL"
        dispatchService -> emailProvider "sends customer notification emails to" "REST/JSON"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram of the Parcel Tracker." {
            include *
            autoLayout
        }
        container parcelTracker "Containers" "Container diagram of the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}
